from __future__ import annotations

import base64
import inspect
import re
import traceback
from pathlib import Path

import pytest

from graph3d.scip_ingest import ingest_scip_json

FIXTURES = Path(__file__).parent / "fixtures"

LEGACY_SOURCES = {
    'symbol': '',
    'import_extension': '',
    'js_import': '',
    'python_import': '',
    'file_node_id': '',
    'scip': '',
    'dedup': '',
}


def _load_legacy(key: str) -> dict[str, object]:
    namespace: dict[str, object] = {"__name__": f"legacy_{key}"}
    source = base64.b64decode(LEGACY_SOURCES[key]).decode("utf-8")
    exec(compile(source, f"<legacy_{key}>", "exec"), namespace)
    return namespace


def _legacy_cases(key: str, *, max_line: int | None = None, min_line: int | None = None):
    namespace = _load_legacy(key)
    prefix = f"legacy_{key}_"
    cases = [
        (name, func)
        for name, func in namespace.items()
        if name.startswith(prefix) and callable(func)
    ]
    if min_line is not None:
        cases = [(name, func) for name, func in cases if func.__code__.co_firstlineno >= min_line]
    if max_line is not None:
        cases = [(name, func) for name, func in cases if func.__code__.co_firstlineno <= max_line]
    return sorted(cases, key=lambda item: item[1].__code__.co_firstlineno)


def _safe_case_name(name: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", name)[:120]


def _run_cases(cases, tmp_path: Path | None = None, monkeypatch: pytest.MonkeyPatch | None = None) -> None:
    failures: list[str] = []
    for name, func in cases:
        try:
            params = inspect.signature(func).parameters
            if not params:
                func()
            elif list(params) == ["tmp_path"] and tmp_path is not None:
                case_path = tmp_path / _safe_case_name(name)
                case_path.mkdir(parents=True, exist_ok=True)
                func(case_path)
            elif list(params) == ["monkeypatch", "tmp_path"] and tmp_path is not None and monkeypatch is not None:
                case_path = tmp_path / _safe_case_name(name)
                case_path.mkdir(parents=True, exist_ok=True)
                func(monkeypatch, case_path)
            else:
                failures.append(f"{name}: unsupported signature {list(params)}")
        except Exception:
            failures.append(f"{name}:\n{traceback.format_exc()}")
    assert not failures, "\n\n".join(failures)


def test_symbol_resolution(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    cases = _legacy_cases("symbol")
    _run_cases(cases, tmp_path, monkeypatch)


def test_import_resolution_js_ts(tmp_path: Path) -> None:
    cases = [*_legacy_cases("import_extension"), *_legacy_cases("js_import")]
    _run_cases(cases, tmp_path)


def test_import_resolution_python(tmp_path: Path) -> None:
    _run_cases(_legacy_cases("python_import"), tmp_path)


def test_file_node_id_spec(tmp_path: Path) -> None:
    _run_cases(_legacy_cases("file_node_id"), tmp_path)


def test_scip_ingest_core() -> None:
    failures: list[str] = []
    bad_inputs = [None, "a string", 42, 3.14, True, [], [1, 2, 3]]
    for bad_input in bad_inputs:
        result = ingest_scip_json(bad_input)
        if result != {"nodes": [], "edges": []}:
            failures.append(f"bad_input={bad_input!r}: got {result!r}")
    try:
        _run_cases(_legacy_cases("scip", max_line=518))
    except AssertionError as exc:
        failures.append(str(exc))
    assert not failures, "\n\n".join(failures)


def test_scip_ingest_edge_cases() -> None:
    _run_cases(_legacy_cases("scip", min_line=541))


def test_dedup(tmp_path: Path) -> None:
    _run_cases(_legacy_cases("dedup"), tmp_path)
